import * as THREE from './vendor/three.module.js';
// Plumes anchored to the two real Octavia exhaust tips; no exhaust on the Tesla.
const vertexShader=`varying vec2 flameUV;varying vec3 flameNormal;void main(){flameUV=uv;flameNormal=normalize(normalMatrix*normal);gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`;
const fragmentShader=`uniform float clock;uniform float core;varying vec2 flameUV;varying vec3 flameNormal;float noise(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}void main(){float v=flameUV.y;float ripple=.65+.35*sin(flameUV.x*31.0+v*25.0-clock*51.0)*sin(v*43.0-clock*23.0);float grain=.76+.24*noise(floor(flameUV*vec2(14.,24.)+vec2(clock*8.,-clock*30.)));float alpha=pow(max(0.,1.-v),.55)*(.35+.65*min(1.,abs(flameNormal.z)*3.))*ripple*grain;vec3 color=mix(vec3(.23,.57,1.),vec3(1.,.21,.025),smoothstep(.08,.7,v));color=mix(color,vec3(.82,.95,1.),core*(1.-v)*.85);gl_FragColor=vec4(color*1.55,min(.98,alpha*(core>.5?1.3:1.15)));}`;
export function createNitroExhaust(car){const group=new THREE.Group();group.name='Llamas de nitro en escapes';car.add(group);const material=core=>new THREE.ShaderMaterial({uniforms:{clock:{value:0},core:{value:core}},vertexShader,fragmentShader,transparent:true,depthWrite:false,blending:core?THREE.AdditiveBlending:THREE.NormalBlending,toneMapped:false,side:THREE.DoubleSide}),outer=material(0),inner=material(1),geometry=new THREE.ConeGeometry(.115,1,12,4,true),cores=[];for(const side of [-1,1]){const nozzle=new THREE.Group();nozzle.position.set(side*.63,.30,2.40);for(const [mat,scale]of [[outer,1],[inner,.57]]){const flame=new THREE.Mesh(geometry,mat);flame.rotation.x=Math.PI/2;flame.position.z=scale*.5;flame.scale.set(scale,scale,scale);nozzle.add(flame);cores.push({flame,scale});}group.add(nozzle);}const glow=new THREE.PointLight('#ff9b40',1.5,4,2);glow.position.set(0,.4,2.9);group.add(glow);group.visible=false;return {update(active,time,speed){group.visible=!!active;if(!active)return;outer.uniforms.clock.value=inner.uniforms.clock.value=time;const pulse=1.05+.21*Math.sin(time*71)+.12*Math.sin(time*113);glow.intensity=1.2*pulse;for(const {flame,scale}of cores){const length=scale*(1.05+Math.max(0,speed-60)*.024)*pulse;flame.scale.y=length;flame.position.z=length*.5;}},dispose(){outer.dispose();inner.dispose();geometry.dispose();group.removeFromParent();},group};}
